import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.CbQjVMS6.js";const p=JSON.parse('{"title":"Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1793948662000}'),s={name:"faq.md"};function i(n,e,h,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="about-the-projects" tabindex="-1">About the projects <a class="header-anchor" href="#about-the-projects" aria-label="Permalink to &quot;About the projects&quot;">​</a></h2><h3 id="are-piekbs-piemdm-and-pieplm-separate-products" tabindex="-1">Are PieKBS, PieMDM and PiePLM separate products? <a class="header-anchor" href="#are-piekbs-piemdm-and-pieplm-separate-products" aria-label="Permalink to &quot;Are PieKBS, PieMDM and PiePLM separate products?&quot;">​</a></h3><p>Yes. They solve different problems and can be adopted independently. PieKBS manages knowledge for agents, PieMDM manages enterprise master data, and PiePLM documents a product lifecycle approach for manufacturers. See <a href="/projects">Projects</a> for the boundaries between them.</p><h3 id="are-the-projects-free" tabindex="-1">Are the projects free? <a class="header-anchor" href="#are-the-projects-free" aria-label="Permalink to &quot;Are the projects free?&quot;">​</a></h3><p>The source code is released under the MIT License. You may use, modify and distribute it, including in commercial settings, subject to the terms of the license. There are no licence fees and no paid tiers.</p><h3 id="do-i-need-a-cloud-account" tabindex="-1">Do I need a cloud account? <a class="header-anchor" href="#do-i-need-a-cloud-account" aria-label="Permalink to &quot;Do I need a cloud account?&quot;">​</a></h3><p>No. The projects are designed to be self-hosted. PieKBS runs as a local binary with a local SQLite index. PieMDM can be started with Docker Compose on your own infrastructure.</p><h3 id="which-project-should-i-start-with" tabindex="-1">Which project should I start with? <a class="header-anchor" href="#which-project-should-i-start-with" aria-label="Permalink to &quot;Which project should I start with?&quot;">​</a></h3><ul><li>If your problem is “our agent cannot find or cite our documents”, start with <a href="https://pieteams.github.io/piekbs/" target="_blank" rel="noreferrer">PieKBS</a>.</li><li>If your problem is “our customer, supplier or product data is inconsistent across systems”, start with <a href="https://pieteams.github.io/piemdm/" target="_blank" rel="noreferrer">PieMDM</a>.</li><li>If your problem is “we are a small manufacturer and PLM suites are too expensive”, read <a href="https://pieteams.github.io/pieplm/" target="_blank" rel="noreferrer">PiePLM</a> and evaluate the blueprint.</li></ul><h3 id="what-is-the-status-of-pieplm" tabindex="-1">What is the status of PiePLM? <a class="header-anchor" href="#what-is-the-status-of-pieplm" aria-label="Permalink to &quot;What is the status of PiePLM?&quot;">​</a></h3><p>PiePLM is in the documentation and design phase. The public repository contains the project description, market research, architecture notes and module design. The website is explicit about what exists and what is planned; it does not ship an executable release yet.</p><h2 id="using-the-documentation" tabindex="-1">Using the documentation <a class="header-anchor" href="#using-the-documentation" aria-label="Permalink to &quot;Using the documentation&quot;">​</a></h2><h3 id="can-i-translate-the-documentation" tabindex="-1">Can I translate the documentation? <a class="header-anchor" href="#can-i-translate-the-documentation" aria-label="Permalink to &quot;Can I translate the documentation?&quot;">​</a></h3><p>Yes, provided you preserve attribution and link back to the original page. Some projects already include community translations. Open an issue before starting a full translation so that work is not duplicated.</p><h3 id="i-found-an-error-where-do-i-report-it" tabindex="-1">I found an error. Where do I report it? <a class="header-anchor" href="#i-found-an-error-where-do-i-report-it" aria-label="Permalink to &quot;I found an error. Where do I report it?&quot;">​</a></h3><p>Open an issue in the repository for the affected project. For this website, use the <a href="https://github.com/pieteams/pieteams.github.io/issues" target="_blank" rel="noreferrer">website issue tracker</a>. Include the page URL and the correction you suggest.</p><h3 id="can-i-use-screenshots-or-excerpts-in-my-own-article" tabindex="-1">Can I use screenshots or excerpts in my own article? <a class="header-anchor" href="#can-i-use-screenshots-or-excerpts-in-my-own-article" aria-label="Permalink to &quot;Can I use screenshots or excerpts in my own article?&quot;">​</a></h3><p>Short quotations with a link to the source are welcome. For longer reproductions, ask first through the relevant repository&#39;s issue tracker.</p><h2 id="privacy-cookies-and-advertising" tabindex="-1">Privacy, cookies and advertising <a class="header-anchor" href="#privacy-cookies-and-advertising" aria-label="Permalink to &quot;Privacy, cookies and advertising&quot;">​</a></h2><h3 id="does-this-website-use-cookies" tabindex="-1">Does this website use cookies? <a class="header-anchor" href="#does-this-website-use-cookies" aria-label="Permalink to &quot;Does this website use cookies?&quot;">​</a></h3><p>Yes. The site uses Google Analytics to understand aggregate traffic and Google AdSense to display advertising. Both services may set cookies. The <a href="/privacy">privacy policy</a> lists the categories, purposes and ways to opt out.</p><h3 id="can-i-use-the-site-without-personalised-advertising" tabindex="-1">Can I use the site without personalised advertising? <a class="header-anchor" href="#can-i-use-the-site-without-personalised-advertising" aria-label="Permalink to &quot;Can I use the site without personalised advertising?&quot;">​</a></h3><p>Yes. You can disable personalised advertising in <a href="https://www.google.com/settings/ads" target="_blank" rel="noreferrer">Google Ads Settings</a> or opt out of third-party advertising cookies at <a href="https://www.aboutads.info/choices/" target="_blank" rel="noreferrer">aboutads.info</a>. You can also block cookies in your browser; the documentation remains readable.</p><h3 id="do-you-sell-personal-data" tabindex="-1">Do you sell personal data? <a class="header-anchor" href="#do-you-sell-personal-data" aria-label="Permalink to &quot;Do you sell personal data?&quot;">​</a></h3><p>No. We do not sell personal information. We do not require an account to read the documentation.</p><h3 id="why-does-the-site-show-ads" tabindex="-1">Why does the site show ads? <a class="header-anchor" href="#why-does-the-site-show-ads" aria-label="Permalink to &quot;Why does the site show ads?&quot;">​</a></h3><p>Advertising covers the cost of hosting and maintaining the documentation. Ads are served by Google; we do not control which individual ads appear. Advertising does not affect the technical content or comparisons on this site.</p><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><h3 id="how-do-i-contribute-code" tabindex="-1">How do I contribute code? <a class="header-anchor" href="#how-do-i-contribute-code" aria-label="Permalink to &quot;How do I contribute code?&quot;">​</a></h3><p>Read <code>CONTRIBUTING.md</code> in the repository, open an issue to discuss a significant change, then submit a pull request. Small fixes such as typos and broken links can go straight to a pull request.</p><h3 id="do-you-accept-feature-requests" tabindex="-1">Do you accept feature requests? <a class="header-anchor" href="#do-you-accept-feature-requests" aria-label="Permalink to &quot;Do you accept feature requests?&quot;">​</a></h3><p>Yes. Open an issue describing the problem, the proposed behaviour and the use case. Requests are prioritised against the project roadmap and maintainer capacity.</p><h3 id="how-can-i-support-the-projects" tabindex="-1">How can I support the projects? <a class="header-anchor" href="#how-can-i-support-the-projects" aria-label="Permalink to &quot;How can I support the projects?&quot;">​</a></h3><p>Use them, report bugs, improve the documentation, or share them with a team that has the problem they solve. Starring a repository helps others discover it.</p>',35)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
